import React from "react";
import DashboardCard from "./component/DashboardCard";
import HighestOrders from "./component/HighestOrders";
import InventoryComponent from "./component/InventoryCard";
import OrderDetails from "./component/OrderDetails";
import PaymentSummary from "./component/PaymentSummary";
import RepeatCustomer from "./component/RepeatCustomers";
import RevenueChart from "./component/RevenueChart";
import TopCustomersTable from "./component/TopCustomersTable";
import TopProductsTable from "./component/TopProductsTable";

export default function Analytics() {
    return (
        <>
        <div className="container mt-4">
            <h2 className="mb-4">Analystics Dashboard</h2>
            <DashboardCard/>
            <HighestOrders/>
            <InventoryComponent/>
            <OrderDetails/>
            <PaymentSummary/>
            <RepeatCustomer/>
            <RevenueChart/>
            <TopCustomersTable/>
            <TopProductsTable/>
            </div>
        </>
    )
}
